    if id == 1 { Some(user) } else { None }
}

// Result — Operation kann fehlschlagen
fn parse_number(s: &str) -> Result<i32, String> {
    s.parse::<i32>().map_err(|e| e.to_string())
}

// ? Operator — Error Propagation
